// Turns Google Drive's file details into one clean item per file.

const files = [];

$input.all().forEach((item, index) => {
  const f = item.json;
  if (!f || !f.id) return;                                          // not a file
  if (f.mimeType === 'application/vnd.google-apps.folder') return; // skip folders

  files.push({
    json: {
      drive_file_id: f.id,
      file_name: f.name || '(no name)',
      mime_type: f.mimeType || '',
      file_url: f.webViewLink || `https://drive.google.com/file/d/${f.id}/view`,
      // The file's fingerprint: identical files have the same content_key
      content_key: f.md5Checksum ? `md5:${f.md5Checksum}` : `drive:${f.id}:v${f.version || 0}`,
      size_bytes: f.size ? Number(f.size) : null,
      created_time: f.createdTime || null,
    },
    pairedItem: { item: index }, // remembers which Drive file this item came from
  });
});

// Oldest upload first, so an older CV is read before its newer version
files.sort((a, b) => String(a.json.created_time || '').localeCompare(String(b.json.created_time || '')));

return files;

// Turns the results for every file into one Slack message.
// Anything a human should look at goes in a "Needs a human" list with a link to the file.

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const linkTo = (r) => (r.file_url ? `<${r.file_url}|${esc(r.file_name).replace(/\|/g, '/')}>` : `\`${esc(r.file_name)}\``);

const results = $input.all().map((item, i) => {
  const r = item.json || {};
  if (r.outcome) return r;
  // The sub-workflow crashed for this file (for example the database was unreachable).
  let file = {};
  try { file = $('Standardize file info').itemMatching(i).json; } catch (e) { /* unknown file */ }
  return {
    outcome: 'error',
    file_name: file.file_name || 'unknown file',
    file_url: file.file_url,
    message: `Processing crashed: ${r.error || 'no result'}. It will be retried on the next run.`,
  };
});

const by = (outcome) => results.filter((r) => r.outcome === outcome);
const flagsOf = (r) => (Array.isArray(r.flags) ? r.flags : []);

const ATTENTION_LABEL = {
  unreadable: 'Unreadable',
  unsupported: 'Not supported',
  not_a_cv: 'Not a CV',
  error: 'Error',
  possible_duplicate: 'Same name as someone else',
};

const attention = [];
for (const r of results) {
  if (ATTENTION_LABEL[r.outcome]) {
    attention.push(`• ${linkTo(r)} — *${ATTENTION_LABEL[r.outcome]}:* ${esc(r.message)}`);
  } else if (flagsOf(r).includes('read_from_scan')) {
    attention.push(`• ${linkTo(r)} — *Read from a scan, please double-check:* ${esc(r.message)}`);
  } else if (flagsOf(r).includes('check_which_is_newer')) {
    attention.push(`• ${linkTo(r)} — *Check the version:* ${esc(r.message)}`);
  }
}

const names = (list) => {
  const seen = new Map();   // one name per person (two people can share a name)
  for (const r of list) seen.set(r.candidate_id || r.file_name, esc(r.candidate_name || r.file_name));
  const unique = [...seen.values()];
  return unique.slice(0, 8).join(', ') + (unique.length > 8 ? ` and ${unique.length - 8} more` : '');
};

const lines = [`*CV intake* · ${results.length} file${results.length === 1 ? '' : 's'} checked`];
const add = (emoji, label, list, showNames = true) => {
  if (list.length) lines.push(`${emoji} ${label}: *${list.length}*${showNames ? ' — ' + names(list) : ''}`);
};
add('✅', 'New candidates', by('new_candidate').concat(by('possible_duplicate')));
add('🔁', 'Updated CVs (old version replaced)', by('updated'));
add('🗂️', 'Older versions stored', by('older_version'));
add('👯', 'Duplicates merged', by('duplicate').concat(by('exact_duplicate')));
add('⏭️', 'Already in the database', by('already_processed'), false);

if (attention.length) {
  lines.push('', `⚠️ *Needs a human (${attention.length})*`);
  lines.push(...attention.slice(0, 25));
  if (attention.length > 25) lines.push(`…and ${attention.length - 25} more. See the CV library in the portal.`);
} else {
  lines.push('', 'Nothing needs your attention. 👍');
}

const counts = {};
for (const r of results) counts[r.outcome] = (counts[r.outcome] || 0) + 1;

return [{ json: { slack_text: lines.join('\n'), counts, needs_attention: attention.length } }];
